SettingsService.set("auto_allocate_wounds", true)
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) == 2:
		for m in u.models:
			m["wounds"] = 99
			m["current_wounds"] = 99
return true

var u = GameState.get_unit("U_TANKBUSTAS_A")
var t = GameState.get_unit("U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H")
var m = RulesEngine.ork11e_ab_mods(u, t, {"name": "Busta Rokkit Launcha \u2013 Hunter", "type": "Ranged"}, false, GameState.state, [])
print("[wp-o6] mods ", "U_TANKBUSTAS_A", " -> ", "U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H", ": ", m)
return int(m.ap) == 1 and bool(m.lethal)

var u = GameState.get_unit("U_TANKBUSTAS_A")
var t = GameState.get_unit("U_TELEMON_HEAVY_DREADNOUGHT_I")
var m = RulesEngine.ork11e_ab_mods(u, t, {"name": "Busta Rokkit Launcha \u2013 Hunter", "type": "Ranged"}, false, GameState.state, [])
print("[wp-o6] mods ", "U_TANKBUSTAS_A", " -> ", "U_TELEMON_HEAVY_DREADNOUGHT_I", ": ", m)
return int(m.ap) == 0 and not bool(m.lethal)

